(function () {
    cc.ChickenFightBetView = cc.Class({
        extends: cc.Component,
        properties: {
            layoutButtonBets: cc.Node,
            lbPhonixBet: cc.Label,
            lbDragonBet: cc.Label,
            lbTieBet: cc.Label,
            lbBigTieBet: cc.Label,
            //Btn Bet again
            btnBetX2: cc.Button,
            btnBetAgain: cc.Button,
            btnPrevChipPool: cc.Button,
            btnNextChipPool: cc.Button,
            btnChips: [cc.Button],
            poolListContent: cc.Node,
            lbUserBetDragon: cc.Label,
            lbUserBetPhonix: cc.Label,
            lbUserBetTie: cc.Label,
            lbUserBetBigTie: cc.Label,
            layoutBtn: cc.Node,
        },

        onLoad: function () {
            this.controller = cc.ChickenFightController.getInstance();
            this.controller.setBetView(this);
            this.reset();
            this.balanceBet = 1000000;
            this.totalBet = 0;
            this.betSide = 0;
            this.nodeChipPress = [];
            //Btn Bet
            const self = this;
            this.btnChips.forEach(function (btnChip) {
                self.nodeChipPress.push(btnChip.node.getChildByName('chipPress'));
            });
            this.btnNextChipPool.interactable = false;
            this.activeBetAgain(false);
        },

        onDestroy: function () {
            this.controller.setBetView(null);
        },

        reset: function () {
            this.lbPhonixBet.string = '0';
            this.lbDragonBet.string = '0';
            this.lbTieBet.string = '0';
            this.lbBigTieBet.string = '0';
            this.lbUserBetDragon.string = '0';
            this.lbUserBetPhonix.string = '0';
            this.lbUserBetTie.string = '0';
            this.lbUserBetBigTie.string = '0';
        },
        setBalanceBet: function (btnBet, value) {
            if (parseInt(value) == this.balanceBet)
                return;

            this.balanceBet = value;

            cc.AudioController.getInstance().playSound(cc.AudioTypes.CHIP_SELECT);

            this.resetChipSelected();
            this.updateCurrentChipSelected(btnBet.target);

            //this.resetStateBtnBet();
            // let btnBetName = btnBet.target._name;
            // let nodeBtnBet = this.layoutButtonBets.getChildByName(btnBetName);

            // let nodeButtons = nodeBtnBet.getComponent(cc.DragonTigerButtonBet);
            // let spriteBtn = nodeBtnBet.getChildren()[0];
            // //spriteBtn.getComponent(cc.Sprite).spriteFrame = nodeButtons.spriteButtons[0];


            // let action = cc.moveTo(0.3, cc.v2(nodeBtnBet.x, -308));
            // action.easing(cc.easeInOut(1));
            // nodeBtnBet.runAction(action);
            // this.balanceBet = parseInt(value);
        },
        resetStateBtnBet: function () {
            let listBtns = this.layoutButtonBets.getChildren();
            listBtns.map(btn => {

                this.resetChipSelected();
                this.updateCurrentChipSelected(btn.target);
            });
        },

        resetChipSelected: function () {
            const self = this;
            this.btnChips.forEach(function (btnChip, index) {
                btnChip.interactable = true;
                cc.tween(btnChip.node).to(0.15, { scale: 1 }).start();

                self.getChipPress(btnChip.node).active = false;
            })

        },

        updateCurrentChipSelected: function (btnChip) {
            btnChip.interactable = false;
            cc.tween(btnChip.node).to(0.3, { scale: 1.2 }).start();

            this.getChipPress(btnChip).active = true;
        },

        getChipPress: function (btnChip) {
            // console.log(btnChip);
            const chipPress = btnChip.getChildByName("chipPress");

            return chipPress;
        },

        onNextPoolClicked: function () {
            const poolListView = this.poolListContent.parent;
            const minX = poolListView.width;
            let newX = this.poolListContent.x - 120;
            if (newX <= minX) {
                newX = minX;
                this.btnNextChipPool.interactable = false;
            }

            cc.tween(this.poolListContent).to(0.3, { position: cc.v2(newX, this.poolListContent.y) }).start();
            this.btnPrevChipPool.interactable = true;
        },

        onPrevPoolClicked: function () {
            const poolListView = this.poolListContent.parent;
            const maxX = this.poolListContent.width;
            let newX = this.poolListContent.x + 120;

            if (newX >= maxX) {
                newX = maxX;
                this.btnPrevChipPool.interactable = false;
            }

            cc.tween(this.poolListContent).to(0.3, { position: cc.v2(newX, this.poolListContent.y) }).start();
            this.btnNextChipPool.interactable = true;
        },

        //Cap nhat tong tien bet cua player
        updateTotalBetValue: function (betSide, totalBet) {
            totalBet = this.formatNumber(totalBet / 1000.0);
            switch (parseInt(betSide)) {
                case cc.ChickenFightBetSide.PHONIX:
                    this.lbPhonixBet.string = totalBet;
                    break;
                case cc.ChickenFightBetSide.DRAGON:
                    this.lbDragonBet.string = totalBet;
                    break;
                case cc.ChickenFightBetSide.TIE:
                    this.lbTieBet.string = totalBet;
                    break;
                case cc.ChickenFightBetSide.BIG_TIE:
                    this.lbBigTieBet.string = totalBet;
                    break;
            }
        },
        formatNumber: function (strNum) {
            strNum = parseInt(strNum);
            return (strNum == 0) ? "" : cc.Tool.getInstance().formatNumber(strNum, 2);
        },
        updateBetInfoFromServer: function (listBet) {
            this.listBet = listBet;
            var self = this;
            listBet.map(betInfo => {
                self.updateBetInfo(betInfo)
            });

        },
        updateBetInfo: function (betInfo) {
            //this.betSide = betInfo.BetSide;
            let betValue = cc.Tool.getInstance().formatNumber(betInfo.BetValue / 1000.0, 2);
            switch (betInfo.BetSide) {
                case cc.ChickenFightBetSide.PHONIX:
                    this.lbPhonixBet.string = betValue;
                    break;
                case cc.ChickenFightBetSide.DRAGON:
                    this.lbDragonBet.string = betValue;
                    break;
                case cc.ChickenFightBetSide.TIE:
                    this.lbTieBet.string = betValue;
                    break;
                case cc.ChickenFightBetSide.BIG_TIE:
                    this.lbBigTieBet.string = betValue;
                    break;
            }
        },
        setBetSide: function (element, side) {
            this.betSide = parseInt(side);
            cc.AudioController.getInstance().playSound(cc.AudioTypes.CHIP_BET);
            if (cc.BalanceController.getInstance().getBalance() < this.balanceBet) {
                cc.PopupController.getInstance().showMessage('Số dư không đủ');
            } else {
                cc.ChickenFightController.getInstance().sendRequestOnHub(cc.MethodHubName.BET, this.balanceBet, this.betSide);
                this.activeBetAgain(false);
            }

        },
        sendRequestBet: function (betValue, betSide) {
            return cc.ChickenFightController.getInstance().sendRequestOnHub(cc.MethodHubName.BET, betValue, betSide);
        },
        //Bet lai
        onBetAgain: function (sender, unit) {
            unit = parseInt(unit); //He so bet
            let logBet = cc.ChickenFightController.getInstance().getBetLogBySessionID(cc.ChickenFightController.getInstance().getBetLogSession());
            // console.log({logBet});

            if (logBet.length === 0) {
                cc.PopupController.getInstance().showMessage("Chưa có dữ liệu của phiên trước.");
                return;
            }
            for (let i = 1; i <= unit; i++) {
                logBet.map((betData, index) => {
                    let timeOut = setTimeout(function () {
                        if (cc.ChickenFightController.getInstance().getCurrentState() === cc.ChickenFightPharse.BETTING && betData.sessionID === cc.ChickenFightController.getInstance().getBetLogSession() - 1) {
                            this.sendRequestBet(betData.value, betData.betSide);
                        } else {
                            try {
                                clearTimeout(timeOut);
                            } catch (e) {
                                console.log(e);
                            }
                        }
                    }.bind(this), index * 500 * i);
                }, this);
            }
            this.activeBetAgain(false);
        },
        //Disable button bet lai, bet x2
        activeBetAgain: function (active) {
            this.layoutBtn.active = active;
            // this.btnBetAgain.interactable = isDisable;
            // this.btnBetX2.interactable = isDisable;
            // let color = cc.Color.WHITE;
            // if (isDisable) {
            //     color = cc.Color.GRAY;
            // }
            // this.nodeBetX2.color = color;
            // this.nodeBetAgain.color = color;
        },
        getBetSide: function () {
            return this.betSide;
        },

        updateTotalBet: function (sessionInfo) {
            this.lbPhonixBet.string = cc.Tool.getInstance().formatNumber(sessionInfo.TotalBetPhonix / 1000.0);
            this.lbDragonBet.string = cc.Tool.getInstance().formatNumber(sessionInfo.TotalBetDragon / 1000.0);
            this.lbTieBet.string = cc.Tool.getInstance().formatNumber(sessionInfo.TotalBetTie / 1000.0);
            this.lbBigTieBet.string = cc.Tool.getInstance().formatNumber(sessionInfo.TotalBetTie / 1000.0);

        },

        updateTotalUserBetSide: function (betSide, total) {
            if (betSide == 1) {
                this.lbUserBetDragon.string = cc.Tool.getInstance().formatNumber(total / 1000.0);
            } else if (betSide == 2) {
                this.lbUserBetPhonix.string = cc.Tool.getInstance().formatNumber(total / 1000.0);
            } else if (betSide == 3) {
                this.lbUserBetTie.string = cc.Tool.getInstance().formatNumber(total / 1000.0);
            } else if (betSide == 4) {
                this.lbUserBetBigTie.string = cc.Tool.getInstance().formatNumber(total / 1000.0);
            }
        }
    });
}).call(this);